import{_ as s,o as n,c as e,am as p}from"./chunks/framework._FJXuPhs.js";const h=JSON.parse('{"title":"Maven工具_基础使用_mac","description":"","frontmatter":{"title":"Maven工具_基础使用_mac","excerpt":"摘要","date":"2025-11-17 14:34:00","updated":"2025-11-17 14:34:00"},"headers":[],"relativePath":"部署&工具/部署&工具 构建工具/Maven 进阶内容/Maven工具_基础使用_mac.md","filePath":"部署&工具/部署&工具 构建工具/Maven 进阶内容/Maven工具_基础使用_mac.md","lastUpdated":null}'),t={name:"部署&工具/部署&工具 构建工具/Maven 进阶内容/Maven工具_基础使用_mac.md"};function l(i,a,o,c,r,d){return n(),e("div",null,[...a[0]||(a[0]=[p(`<h3 id="安装-maven" tabindex="-1">安装 Maven <a class="header-anchor" href="#安装-maven" aria-label="Permalink to &quot;安装 Maven&quot;">​</a></h3><h4 id="使用-homebrew-安装" tabindex="-1">使用 Homebrew 安装 <a class="header-anchor" href="#使用-homebrew-安装" aria-label="Permalink to &quot;使用 Homebrew 安装&quot;">​</a></h4><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>-- 先看一下是否安装了 homebrew</span></span>
<span class="line"><span>brew --version</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 如果没有安装，进行安装操作</span></span>
<span class="line"><span>/bin/bash -c &quot;$(curl -fsSL https://raw.githubusercontent.com/Homebrew/install/HEAD/install.sh)&quot;</span></span></code></pre></div><p>安装完成后，根据终端提示设置环境变量（特别是在 Apple Silicon Mac 上可能需要额外步骤）</p><p>安装 maven</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>brew install maven</span></span></code></pre></div><p>如果使用 Homebrew 安装 Maven，它会自动处理环境变量，你可以直接验证安装是否成功</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mvn -version</span></span></code></pre></div><h4 id="手动安装" tabindex="-1">手动安装 <a class="header-anchor" href="#手动安装" aria-label="Permalink to &quot;手动安装&quot;">​</a></h4><p>略</p><h3 id="maven-配置" tabindex="-1">Maven 配置 <a class="header-anchor" href="#maven-配置" aria-label="Permalink to &quot;Maven 配置&quot;">​</a></h3><p>Maven 的配置文件位于 <code>~/.m2/settings.xml</code>（用户级别）或 <code>$M2_HOME/conf/settings.xml</code>（全局级别）</p><p>如果 <code>~/.m2/settings.xml</code> 不存在，可以从 Maven 安装目录复制一份</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mkdir -p ~/.m2</span></span>
<span class="line"><span>cp $M2_HOME/conf/settings.xml ~/.m2/</span></span></code></pre></div><p>这里不就建议直接在 maven 的下载后的地址的 conf 目录下的文件直接编辑，而是在用户层面</p><p>你可以先看一下 下载目录</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>mvn version</span></span>
<span class="line"><span></span></span>
<span class="line"><span>-- 复制文件</span></span>
<span class="line"><span>mkdir -p ~/.m2</span></span>
<span class="line"><span>cp /opt/homebrew/Cellar/maven/3.9.11/libexec/conf/settings.xml ~/.m2/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>--这里复制两份，一份是个人，一份是工作</span></span>
<span class="line"><span>mkdir -p ~/.m2/work</span></span>
<span class="line"><span>cp /opt/homebrew/Cellar/maven/3.9.11/libexec/conf/settings.xml ~/.m2/work/</span></span>
<span class="line"><span>mkdir -p ~/.m2/personal</span></span>
<span class="line"><span>cp /opt/homebrew/Cellar/maven/3.9.11/libexec/conf/settings.xml ~/.m2/personal/</span></span>
<span class="line"><span></span></span>
<span class="line"><span>在对应的文件夹下，自己再新建一下仓库文件夹：repository</span></span>
<span class="line"><span>mkdir -p ~/.m2/personal/repository</span></span></code></pre></div><h4 id="配置本地仓库" tabindex="-1">配置本地仓库 <a class="header-anchor" href="#配置本地仓库" aria-label="Permalink to &quot;配置本地仓库&quot;">​</a></h4><p>默认情况下，Maven 使用 <code>~/.m2/repository</code> 目录作为本地仓库。如果你想更改它，编辑 <code>settings.xml</code> 文件</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>nano ~/.m2/settings.xml</span></span></code></pre></div><p>找到并修改 <code>&lt;localRepository&gt;</code> 标签</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;localRepository&gt;/path/to/your/maven/repository&lt;/localRepository&gt;</span></span></code></pre></div><h4 id="配置镜像仓库-国内用户推荐" tabindex="-1">配置镜像仓库（国内用户推荐） <a class="header-anchor" href="#配置镜像仓库-国内用户推荐" aria-label="Permalink to &quot;配置镜像仓库（国内用户推荐）&quot;">​</a></h4><p>为了加速依赖下载，国内用户可以添加 Maven 的镜像仓库，如阿里云镜像。编辑 <code>settings.xml</code>，在 <code>&lt;mirrors&gt;</code> 标签内添加：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;mirror&gt;</span></span>
<span class="line"><span>  &lt;id&gt;aliyun-maven&lt;/id&gt;</span></span>
<span class="line"><span>  &lt;name&gt;Aliyun Maven Repository&lt;/name&gt;</span></span>
<span class="line"><span>  &lt;url&gt;https://maven.aliyun.com/repository/public&lt;/url&gt;</span></span>
<span class="line"><span>  &lt;mirrorOf&gt;central&lt;/mirrorOf&gt;</span></span>
<span class="line"><span>&lt;/mirror&gt;</span></span></code></pre></div><p>实际本机配置的是第二个</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>    &lt;mirror&gt;</span></span>
<span class="line"><span>       &lt;id&gt;alimavenrepository&lt;/id&gt;</span></span>
<span class="line"><span>       &lt;name&gt;aliyun maven repository&lt;/name&gt;</span></span>
<span class="line"><span>       &lt;url&gt;http://maven.aliyun.com/nexus/content/groups/public/&lt;/url&gt;</span></span>
<span class="line"><span>       &lt;mirrorOf&gt;central&lt;/mirrorOf&gt;</span></span>
<span class="line"><span>   &lt;/mirror&gt;</span></span></code></pre></div>`,27)])])}const g=s(t,[["render",l]]);export{h as __pageData,g as default};
